import manifest from "../../public/projects/geospatial-ai/manifest.json";

/**
 * Asset manifest generated by `scripts/process-assets.py` from the genuine
 * project outputs. Every entry points at a crop/resize of a real file — nothing
 * here is synthesised.
 */
export type InferenceSample = {
  /** Original filename in the project export, kept for provenance. */
  source: string;
  image: string;
  "ground-truth": string;
  prediction: string;
  /** Alpha-only version of the same mask, so it can be recoloured in the UI. */
  "prediction-mask": string;
  "ground-truth-mask": string;
};

export type FeatureClass = {
  slug: string;
  label: string;
  samples: InferenceSample[];
};

export type TileAsset = {
  id: string;
  src: string;
  source: string;
};

export type StitchedAsset = {
  src: string;
  source: string;
  width: number;
  height: number;
};

export const featureClasses = manifest.classes as FeatureClass[];
export const tiles = manifest.tiles as TileAsset[];
export const stitched = manifest.stitched as StitchedAsset | undefined;

/**
 * Display colours for the segmented classes.
 *
 * These are a presentation convention chosen for legibility against the light
 * basemap wash — they are not the colours used in the original project figures
 * and carry no meaning beyond telling the classes apart.
 */
const CLASS_COLOURS: Record<string, string> = {
  bridge: "#b26a00",
  cadastral: "#7b3fa0",
  "rail-line": "#c0392b",
  road: "#a3620a",
  "sewer-line": "#4a7c2f",
  ulu: "#b02e65",
  "water-line": "#0f7b8a",
  "water-point": "#2d5bb9",
  "water-polygon": "#c2185b",
};

const FALLBACK_COLOUR = "#c2185b";

export function classColour(slug: string): string {
  return CLASS_COLOURS[slug] ?? FALLBACK_COLOUR;
}

/**
 * Pick a class whose masks cover a large, visually legible area so the pipeline
 * animation and the comparison slider read clearly at a glance. Falls back to
 * whatever is available.
 */
function pickScene() {
  const preferred = ["water-polygon", "road", "water-line", "rail-line"];
  for (const slug of preferred) {
    const match = featureClasses.find(
      (c) => c.slug === slug && c.samples.length > 0,
    );
    if (match) return match;
  }
  return featureClasses.find((c) => c.samples.length > 0) ?? null;
}

/** The tile + prediction pair driving the pipeline canvas and compare slider. */
export const demoScene = (() => {
  const cls = pickScene();
  const sample = cls?.samples[0];
  if (!cls || !sample) return null;
  return {
    label: cls.label,
    slug: cls.slug,
    colour: classColour(cls.slug),
    raster: sample.image,
    groundTruth: sample["ground-truth"],
    prediction: sample.prediction,
    predictionMask: sample["prediction-mask"],
    source: sample.source,
  };
})();

/** A tile image and its prediction overlay pair used by the compare slider. */
export const comparePair = demoScene
  ? {
      label: demoScene.label,
      before: demoScene.raster,
      after: demoScene.prediction,
      source: demoScene.source,
    }
  : null;
